#include <bits/stdc++.h>
using namespace std;

long long mod = 1000000007;

int readNextInt() {
    int x;
    cin >> x;
    return x;
}

vector<char> buildUniqueChars(vector<char>& arr, int pos, int length) {
    vector<bool> usedLetter(26, false);
    for (int i = pos - 1; i >= 0 && i >= pos - length; i--) {
        usedLetter[arr[i] - 'a'] = true;
    }
    vector<char> result;
    char c = 'a';
    while ((int)result.size() < length) {
        while (usedLetter[c - 'a']) c++;
        result.push_back(c++);
    }
    return result;
}

int computeOverlap(int a, int b, int startIdx, int endIdx, vector<char>& pattern) {
    int totalSize = 3 * (a + b);
    vector<char> buffer(totalSize);
    for (int i = 0; i < 3; i++) {
        vector<char> uniqueChars = buildUniqueChars(buffer, i * (a + b), a);
        for (int j = 0; j < a; j++) {
            buffer[i * (a + b) + j] = uniqueChars[j];
        }
        for (int j = a; j < a + b; j++) {
            buffer[i * (a + b) + j] = pattern[i];
        }
    }
    int startOffset = startIdx % (a + b);
    int len = endIdx - startIdx + 1;
    vector<char> subBuffer(buffer.begin() + startOffset, buffer.end());
    if ((int)subBuffer.size() > len) {
        subBuffer.resize(len);
    }
    vector<bool> seenLetters(26, false);
    for (char c : subBuffer) {
        seenLetters[c - 'a'] = true;
    }
    int typeCount = 0;
    for (bool found : seenLetters) {
        if (found) typeCount++;
    }
    return typeCount;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int a = readNextInt();
    int b = readNextInt();
    int l = readNextInt() - 1;
    int r = readNextInt() - 1;
    int totalLength = r - l + 1;
    int minCount = totalLength;

    for (char chA = 'a'; chA <= 'z'; chA++) {
        for (char chB = 'a'; chB <= 'z'; chB++) {
            for (char chC = 'a'; chC <= 'z'; chC++) {
                vector<char> pattern = {chA, chB, chC};
                minCount = min(minCount, computeOverlap(a, b, l, r, pattern));
            }
        }
    }
    cout << minCount << "\n";
    return 0;
}

